input.command:
cd /home/user/rork-app && TOKEN=$(git config --get-regexp '^url\..*x-access-token.*insteadof$' 2>/dev/null | head -1 | sed -E 's#^url\.https://x-access-token:([^@]+)@.*#\1#'); if [ -z "$TOKEN" ]; then echo "no token extracted"; exit 1; fi; echo "token extracted: ${#TOKEN} chars (value withheld)"; echo "=== egress + auth test ==="; curl -s -o /tmp/gh.json -w "http_status=%{http_code}\n" -H "Authorization: Bearer $TOKEN" -H "Accept: application/vnd.github+json" https://api.github.com/installation/repositories 2>&1 | tail -2; echo "=== accessible repos ==="; python3 -c "
import json
try:
    d=json.load(open('/tmp/gh.json'))
except Exception as e:
    print('  parse fail:',e); raise SystemExit
if isinstance(d,dict) and 'repositories' in d:
    print('  total:',d.get('total_count'))
    for r in d['repositories']:
        print('  -',r['full_name'],'| push=',r['permissions'].get('push'),'| default=',r['default_branch'])
else:
    print('  response:',str(d)[:300])
"

